import fs from 'node:fs';import path from 'node:path';import assert from'node:assert/strict';import crypto from'node:crypto';import{fileURLToPath}from'node:url';
const here=path.dirname(fileURLToPath(import.meta.url));assert.equal(process.argv.length,4);assert.equal(process.argv[2],'--dist');const dist=path.resolve(process.argv[3]);const read=f=>JSON.parse(fs.readFileSync(path.join(here,f)));const sha=s=>crypto.createHash('sha256').update(s).digest('hex');const es=new Map();for(const f of fs.readdirSync(path.join(dist,'data/chapters')))if(f.endsWith('.json'))for(const e of JSON.parse(fs.readFileSync(path.join(dist,'data/chapters',f))).entries)es.set(e.id,e);
const r=read('records.json').records[0],app=read('append-manifest.json'),map=read('segment-map.json');assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.equal(es.get('ai-agent-5').items[6].a,r.after);const e=es.get(app.entryId);assert.ok(e);assert.deepEqual(e.items.slice(0,4),app.beforeEntry.items);for(const a of app.appends)assert.deepEqual(e.items[a.index],a.expectedItem);assert.equal(e.items.length,7);const dagAppend=read('phase2-exact-collaboration-append.json');assert.deepEqual(dagAppend.beforeEntry,app.afterEntry);assert.deepEqual(e.items.slice(0,6),dagAppend.beforeEntry.items);assert.equal(dagAppend.appends.length,1);const da=dagAppend.appends[0];assert.equal(da.index,6);assert.equal(da.id,'q-agent-repository-orchestration');assert.equal(sha(JSON.stringify(da.expectedItem)),da.expectedItemSha256);assert.deepEqual(e.items[6],da.expectedItem);const exactSeven=structuredClone(dagAppend.beforeEntry);exactSeven.items.push(da.expectedItem);assert.deepEqual(exactSeven,dagAppend.afterEntry);assert.deepEqual(e,dagAppend.afterEntry);
const get=key=>{const [id,q]=key.split('#'),e=es.get(id);return /^\d+$/.test(q)?e.items[+q]:e.items.find(x=>x.id===q);};
for(const x of map.segments){assert.equal(sha(x.before),x.beforeSha256);const dest=get(x.destination);assert.ok(dest);if(x.mode==='exact')assert.ok(dest.a.includes(x.before),x.key);else if(x.mode==='heading-level-only')assert.ok(dest.a.includes(x.before.replaceAll('<h4>','<h3 class="md-h md-h3">').replaceAll('</h4>','</h3>')));else assert.ok(dest.a.includes('id="add-own-distributed-s10974"'));}
const all=r.after+app.appends.map(x=>x.expectedItem.a).join('');for(const m of r.before.matchAll(/<p\b[^>]*>[\s\S]*?<\/p>|<li\b[^>]*>[\s\S]*?<\/li>/g))assert.ok(all.includes(m[0]),'lost original paragraph or wording');
assert.ok(!r.after.includes('审查者只读C'));assert.ok(!r.after.includes('A、B都读v1'));assert.ok(r.after.includes('APPROVED'));assert.ok(r.after.includes('双分析加裁决'));assert.ok(app.appends[0].expectedItem.a.includes('同一PR多作者'));assert.ok(app.appends[1].expectedItem.a.includes('DOM选择器'));assert.ok(app.appends[1].expectedItem.a.includes('fencing'));
console.log(JSON.stringify({passed:true,actualDist:dist,oldQuestionPreserved:true,newQuestions:2,sourceSegments:map.segments.length,overlays:0}));
